\begin{ex}%[8H3H3]
\immini[thm]{
Cho $\Delta{IJQ}$ cân tại ${I}$ có điểm ${K}$ trên cạnh ${JQ}$. Kẻ $KM//IQ$, $KN//IJ$. Chọn khẳng định sai trong các khẳng định sau? 

\choice
{ $\Delta{JKM}$ cân tại ${M}$  }
   { \True $\Delta{NKQ}$ là tam giác đều }
     {  Tứ giác ${IMKN}$ là hình bình hành. }
    { $KM+KN=JM+IM=IJ$  }
}{
\begin{tikzpicture}
            % Định nghĩa các điểm
            \coordinate (A) at (0, 4);
            \coordinate (B) at (-2, 0);
            \coordinate (C) at (2, 0);
            \coordinate (D) at (1, 0);
            \coordinate (M) at (-0.5, 3);
                \coordinate (N) at (1.5, 1);
            % Vẽ tứ giác
            \draw[thick] (A) -- (B) -- (C) -- cycle;
            \draw[thick] (D) -- (M);
            \draw[thick] (D) -- (N);
            % Ghi nhãn các điểm
            \node[above] at (A) {$I $};
            \node[above left] at (B) {$J $};
            \node[above right] at (C) {$Q $};
            \node[below] at (D) {$K $};
            \node[above left] at (M){$M $};
            \node[above right] at (N){$N $};
        \end{tikzpicture}
}
\loigiai{
${IMKN}$ có $IM//KN, IN//MK$ nên là hình bình hành.\\
$\Delta{IJQ}$ cân tại ${I}$ suy ra $\widehat{J}=\widehat{Q}$\\
Mà $MK//IQ$ suy ra $\widehat{Q} =\widehat{JKM}$ (đồng vị) suy ra $\widehat{J} =\widehat{JKM} $ suy ra $\Delta{JKM}$ cân tại ${M}$.\\
Tứ giác ${IMKN}$ là hình bình hành suy ra $KN=IM $\\
Tam giác ${JKM}$ cân tại ${M}$ suy ra $MJ=MK$. Vậy $KM+KN=JM+IM=IJ$.\\
Khẳng định sai là $\Delta{NKQ}$ là tam giác đều.
}\end{ex}

\begin{ex}%[8H3H3]
\immini[thm]{
Cho $\Delta{EFG}$ cân tại ${E}$ có điểm ${H}$ trên cạnh ${FG}$. Kẻ $HI//EG$, $HJ//EF$. Chọn khẳng định sai trong các khẳng định sau? 

\choice
{ \True $\Delta{JHG}$ là tam giác đều }
   {  Tứ giác ${EIHJ}$ là hình bình hành. }
     { $\Delta{FHI}$ cân tại ${I}$  }
    { $HI+HJ=FI+EI=EF$  }
}{
\begin{tikzpicture}
            % Định nghĩa các điểm
            \coordinate (A) at (0, 4);
            \coordinate (B) at (-2, 0);
            \coordinate (C) at (2, 0);
            \coordinate (D) at (1, 0);
            \coordinate (M) at (-0.5, 3);
                \coordinate (N) at (1.5, 1);
            % Vẽ tứ giác
            \draw[thick] (A) -- (B) -- (C) -- cycle;
            \draw[thick] (D) -- (M);
            \draw[thick] (D) -- (N);
            % Ghi nhãn các điểm
            \node[above] at (A) {$E $};
            \node[above left] at (B) {$F $};
            \node[above right] at (C) {$G $};
            \node[below] at (D) {$H $};
            \node[above left] at (M){$I $};
            \node[above right] at (N){$J $};
        \end{tikzpicture}
}
\loigiai{
${EIHJ}$ có $EI//HJ, EJ//IH$ nên là hình bình hành.\\
$\Delta{EFG}$ cân tại ${E}$ suy ra $\widehat{F}=\widehat{G}$\\
Mà $IH//EG$ suy ra $\widehat{G} =\widehat{FHI}$ (đồng vị) suy ra $\widehat{F} =\widehat{FHI} $ suy ra $\Delta{FHI}$ cân tại ${I}$.\\
Tứ giác ${EIHJ}$ là hình bình hành suy ra $HJ=EI $\\
Tam giác ${FHI}$ cân tại ${I}$ suy ra $IF=IH$. Vậy $HI+HJ=FI+EI=EF$.\\
Khẳng định sai là $\Delta{JHG}$ là tam giác đều.
}\end{ex}

